type HookState = 'idle' | 'swinging' | 'firing' | 'reeling' | 'grabbing';

interface Position { x: number; y: number; }
interface Item { id: string; value: number; weight: number; }

class HookStateMachine {
  private state: HookState = 'idle';
  private position: Position = { x: 0, y: 0 };
  private origin: Position = { x: 400, y: 100 };
  private swingAngle: number = 0;
  private swingDirection: number = 1;
  private grabbedItem: Item | null = null;
  private maxLength: number = 300;

  update(deltaTime: number = 1): void {
    switch (this.state) {
      case 'idle':
        this.position = { ...this.origin };
        break;
      case 'swinging':
        this.swingAngle += 0.05 * this.swingDirection * deltaTime;
        if (Math.abs(this.swingAngle) > Math.PI / 3) this.swingDirection *= -1;
        this.position.x = this.origin.x + Math.sin(this.swingAngle) * 50;
        this.position.y = this.origin.y + Math.cos(this.swingAngle) * 50;
        break;
      case 'firing':
        this.position.y += 8 * deltaTime;
        if (this.position.y - this.origin.y >= this.maxLength) this.state = 'reeling';
        break;
      case 'reeling':
        const dy = this.origin.y - this.position.y;
        if (dy <= 5) { this.position = { ...this.origin }; this.state = 'idle'; this.grabbedItem = null; }
        else this.position.y += 5 * deltaTime;
        break;
      case 'grabbing':
        this.state = 'reeling';
        break;
    }
  }

  startSwing(): void { if (this.state === 'idle') this.state = 'swinging'; }
  fire(): void { if (this.state === 'swinging') this.state = 'firing'; }
  catch(item: Item): void { if (this.state === 'firing') { this.grabbedItem = item; this.state = 'grabbing'; } }
  getState(): HookState { return this.state; }
  getPosition(): Position { return { ...this.position }; }
  getGrabbedItem(): Item | null { return this.grabbedItem; }
}

export { HookStateMachine, HookState, Position, Item };

