interface Item { id: string; value: number; weight: number; }
type HookState = 'idle' | 'swinging' | 'firing' | 'reeling' | 'grabbing';

class Hook {
  x: number = 0; y: number = 0;
  state: HookState = 'idle';
  private originX: number = 0; private originY: number = 0;
  private swingAngle: number = 0; private swingDirection: number = 1;
  private grabbedItem: Item | null = null;
  private fireAngle: number = 0;

  constructor(originX: number = 0, originY: number = 0) {
    this.originX = originX; this.originY = originY;
    this.x = originX; this.y = originY;
  }

  update(deltaTime: number = 1): void {
    switch (this.state) {
      case 'swinging':
        this.swingAngle += 0.05 * this.swingDirection * deltaTime;
        if (Math.abs(this.swingAngle) > Math.PI / 3) this.swingDirection *= -1;
        this.x = this.originX + Math.sin(this.swingAngle) * 50;
        this.y = this.originY + Math.cos(this.swingAngle) * 50;
        break;
      case 'firing':
        this.x += Math.sin(this.fireAngle) * 10 * deltaTime;
        this.y += Math.cos(this.fireAngle) * 10 * deltaTime;
        break;
      case 'reeling':
        const dx = this.originX - this.x, dy = this.originY - this.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist <= 5) { this.x = this.originX; this.y = this.originY; this.state = 'idle'; this.grabbedItem = null; }
        else { this.x += (dx / dist) * 8 * deltaTime; this.y += (dy / dist) * 8 * deltaTime; }
        break;
      case 'grabbing': this.state = 'reeling'; break;
    }
  }

  startSwing(): void { if (this.state === 'idle') this.state = 'swinging'; }
  fire(): void { if (this.state === 'swinging') { this.state = 'firing'; this.fireAngle = this.swingAngle; } }
  catchItem(item: Item): void { if (this.state === 'firing') { this.grabbedItem = item; this.state = 'grabbing'; } }
}
